    body: "学習指導要領は1947年（昭和22年）、アメリカの教育使節団の勧告を受けた戦後教育改革の一環として、初めて「学習指導要領 一般編（試案）」の名で作成されました。あくまで教師のための手引き・参考書という位置づけの「試案」であり、経験主義・単元学習の考え方が色濃く、子どもの生活経験や興味・関心を出発点にした学習が重視されました。1951年（昭和26年）には内容を整理した改訂試案が示されています。\n\n大きな転換点となったのが1958年（昭和33年）から1960年（昭和35年）にかけての改訂です。これ以降、学習指導要領は「試案」ではなく文部省（現・文部科学省）の告示として公示されるようになり、法的拘束力を持つ基準とみなされるようになりました。道徳の時間が特設され、戦後の経験主義偏重による学力低下への反省から、教科の系統性を重視する系統学習への転換が図られています。続く1968年（昭和43年）〜1970年（昭和45年）改訂は高度経済成長を背景に「教育内容の現代化」が掲げられ、指導内容が大幅に高度化・増加しました（詰め込み教育とも呼ばれます）。\n\nその反動として、1977年（昭和52年）・1978年（昭和53年）改訂では、詰め込みすぎた授業についていけない子どもの増加や過度な受験競争への反省から、「ゆとりと充実」が掲げられ、各教科の標準授業時数が初めて削減に転じました。1989年（平成元年）改訂では、社会の変化に主体的に対応する力を重視する「新学力観」が示され、小学校低学年の社会・理科を統合した教科「生活科」が新設されています。\n\n1998年（平成10年）・1999年（平成11年）改訂は、いわゆる「ゆとり教育」の到達点とされる改訂です。完全学校週5日制の実施に合わせて授業時数・教育内容が大きく削減される一方、自ら課題を見つけ考える「生きる力」の育成を掲げて、教科の枠を超えた「総合的な学習の時間」が新設されました。しかしその後、国際学力調査（PISA等）の結果低下も一因となって学力低下批判が強まり、2003年（平成15年）には学習指導要領はあくまで最低基準であることを明確化する一部改正が行われ、事実上の路線修正が図られています。\n\nこの流れを受けた2008年（平成20年）・2009年（平成21年）改訂は、「脱ゆとり教育」とも呼ばれ、主要教科を中心に授業時数・学習内容が増加に転じました。ゆとりでも詰め込みでもなく、知識・道徳・体力のバランスの取れた「生きる力」を実質化することが目指されています。\n\n現行の2017年（平成29年）・2018年（平成30年）改訂（幼稚園教育要領は2017年改訂）は戦後9回目の全面改訂にあたります。「何を学ぶか」に加えて「どのように学ぶか」「何ができるようになるか」を重視し、全教科等を貫く「資質・能力の三つの柱」（知識及び技能／思考力・判断力・表現力等／学びに向かう力・人間性等）を明確化しました。授業改善の視点として「主体的・対話的で深い学び」を掲げ、学校が組織的に教育課程を編成・実施・評価・改善する「カリキュラム・マネジメント」の確立を求めている点が特徴です。\n\nこうして振り返ると、学習指導要領の歴史は、子どもの経験や生活を重視する「経験主義」と、教科の体系的な知識を重視する「系統主義」との間、あるいは学習内容・授業時数を減らす「ゆとり」路線と増やす「詰め込み・脱ゆとり」路線との間を、振り子のように行き来してきた歴史と整理することができます。改訂のたびに中央教育審議会（中教審）の答申を経て具体化される点は一貫しており、次期改訂に向けた検討も継続的に行われています。",
