    body: "学級編制基準とは、公立の小学校・中学校において1学級を編制する際の児童生徒数の標準を定めたものです。正式には「公立義務教育諸学校の学級編制及び教職員定数の標準に関する法律」(通称・義務標準法)に規定されており、都道府県教育委員会が具体的な学級編制や教職員配置の基準を定める際の根拠となります。\n\n長らく1学級の上限は40人とされてきましたが、きめ細かな指導体制の実現などを目的として、2021年の法改正により小学校について2021年度から5年間かけて段階的に35人へ引き下げることが決定され、2025年度には小学校全学年で35人学級が実現しました。中学校についても引き下げの検討が進められています。\n\n学級編制基準は、教職員定数の算定や少人数学級の実現可能性に直結するため、教育の質を左右する重要な制度的基盤とされています。地方公共団体が独自に基準を下回る学級編制を行う場合には、追加の教員配置など財政的な工夫が必要になることもあり、基準の見直しは常に国と地方の財政負担の議論と結びついています。",
