    body: "私学助成とは、私立学校振興助成法などに基づき、国や都道府県が私立の幼稚園・小中高等学校・大学等に対して行う財政的な補助の総称です。私立学校は建学の精神に基づく独自の教育を担う一方、公教育の一翼を担う存在でもあることから、教育条件の維持向上や学費負担の軽減、経営の健全化などを目的として助成が行われています。\n\n代表的なものに、都道府県が実施する私立高等学校等経常費助成費補助や、国が私立大学等に交付する私立大学等経常費補助金があります。あわせて、家計急変等に対応した授業料減免や、高等学校等就学支援金制度による授業料実質無償化なども、広い意味で私学助成の一環として位置づけられます。\n\n私学助成には、公費投入の妥当性や教育内容への公的関与のあり方をめぐる議論が伴います。日本国憲法第89条が定める公の財産の私的支配下にある団体への支出制限との関係も、私学助成の合憲性をめぐる論点として古くから議論されてきましたが、私立学校振興助成法において助成を受ける学校法人が一定の会計報告義務を負うことなどにより、公的関与とのバランスが図られています。",
