    body: "教育振興基本計画とは、2006年に改正された教育基本法第17条の規定に基づき、政府が策定する教育に関する総合的かつ計画的な施策の推進のための基本計画です。教育の理念や目指すべき社会像を示したうえで、今後おおむね5年間に取り組むべき施策の方向性や、成果を測るための指標を体系的に整理している点が特徴です。\n\n最初の計画は2008年に策定され、以後、社会の変化や答申の内容を反映しながら第2期・第3期と改定が重ねられてきました。地方公共団体は、国の計画を参酌しつつ、地域の実情に応じた教育振興基本計画を定めるよう努めることとされており、国と地方の教育施策をつなぐ役割も担っています。\n\nこの計画は、生涯学習社会の実現や教育の質の向上、教育格差の是正、グローバル化・情報化への対応など、時代ごとの重要課題を反映しながら、教育行政全体の方向性を規定する指針として機能しています。中央教育審議会の審議を経て閣議決定される点も特徴で、国や地方の予算編成、各種施策の優先順位づけにも大きな影響を与えます。",
