    body: "少人数学級とは、学級編制基準で定められた標準よりも少ない人数で1学級を編制することで、教員が児童生徒一人ひとりに向き合う時間を増やし、きめ細かな指導を実現しようとする施策の総称です。都道府県や市町村が独自の予算で教員を加配し、国の標準を下回る学級編制を実現している例も多く見られます。\n\n国レベルでも、2021年の義務標準法改正により、公立小学校の学級編制の標準が段階的に40人から35人へ引き下げられ、2025年度には小学校全学年での35人学級が実現しました。少人数学級は、いじめや不登校への早期対応、個別最適な学びの実現、教員の多忙化解消といった観点からも期待されています。\n\n一方で、少人数学級の効果については学力向上との因果関係を含めて研究者の間でも評価が分かれており、教員不足や財政負担といった実施上の課題も指摘されています。少人数指導(習熟度別指導など学級を分けずに集団規模を小さくする指導方法)とは区別される概念であり、両者を組み合わせて活用する自治体も少なくありません。",
