    body: "教育の政治的中立性とは、学校における教育活動が、特定の政党その他の政治的団体の主義主張に偏ることなく、公正かつ中立な立場で行われるべきであるとする原則です。教育基本法第14条は、良識ある公民として必要な政治的教養は教育上尊重されるべきものとしつつ、法律に定める学校が特定の政党を支持し、または反対するための政治教育その他政治的活動をしてはならないと定めています。\n\nこの原則を担保する仕組みとして、教育公務員特例法は公立学校の教育公務員に対する政治的行為の制限を、教育委員会制度は首長からの一定の独立性を保つ組織のあり方を、それぞれ定めています。教育委員会が合議制の執行機関として設置されているのも、教育行政が特定の政治勢力の影響を受けにくくするための制度的工夫の一つとされます。\n\n一方で、2015年の公職選挙法改正による選挙権年齢の18歳への引き下げ以降、主権者教育の充実が求められる中で、政治的中立性を保ちながら現実の政治的事象を扱う授業をどう実施するかは、学校現場における重要な課題となっています。",
