    body: "教育公務員特例法とは、公立学校の校長及び教員並びに教育委員会の専門的教育職員(指導主事等)の職務とその責任の特殊性に基づき、任免、人事評価、給与、分限及び懲戒、服務、研修等について、一般の地方公務員に関する規定の特例を定める法律です。1949年に制定され、教育公務員としての専門性や職務の特殊性を踏まえた身分保障や服務の在り方を規定しています。\n\n代表的な規定として、教員の研修に関する体系的な定めがあり、初任者研修や中堅教諭等資質向上研修など、法定研修の実施を教育委員会等に義務づけています。また、教育公務員の政治的行為の制限についても、一般の地方公務員より広い範囲(全国規模)で国家公務員法の規定を準用する特例が置かれている点が特徴です。\n\nこの法律は、教育の政治的中立性の確保や、教員が絶えず研究と修養に努めるべきとする教育基本法の理念を制度的に支える基盤として位置づけられており、教員の資質能力の向上や身分の安定を通じて、学校教育の質を確保することを目的としています。教員免許更新制の廃止後は、この法律に基づく研修等記録の仕組みが、教員の学びを支える重要な制度として位置づけられています。",
