    body: "総合教育会議とは、地方公共団体の首長と教育委員会が、教育に関する重点施策や教育を行うための諸条件の整備等について協議・調整するために設置される会議体です。2011年の大津市いじめ自殺事件を契機とした教育委員会制度改革の一環として、2014年の地方教育行政の組織及び運営に関する法律の改正により新設され、2015年度からすべての地方公共団体に設置が義務づけられました。\n\n総合教育会議は首長が招集し、首長と教育委員会がそれぞれの権限を尊重しつつ、教育行政の大綱の策定や、いじめによる自殺の防止など児童生徒等の生命または身体の保護に緊急の必要がある場合の措置などについて協議します。同時に、首長が地域の教育、学術及び文化の振興に関する総合的な施策の大綱を策定することも定められました。\n\nこの制度改正では、教育委員長と教育長を一本化した新「教育長」を置き、首長が議会の同意を得て任命する仕組みも導入されました。総合教育会議はあくまで協議・調整の場であり、教科書採択や教職員人事など教育委員会の執行権限そのものは従来どおり維持されている点に留意が必要です。",
