    body: "義務教育費国庫負担制度とは、都道府県及び政令指定都市が負担する公立の小学校・中学校・義務教育学校・中等教育学校前期課程・特別支援学校小中学部の教職員の給与費について、その一部を国が負担する制度です。義務教育費国庫負担法に基づき、教育の機会均等とその水準の維持向上を図ることを目的として運用されています。\n\n制度創設当初、国の負担割合は2分の1でしたが、国と地方の税財政関係を見直す「三位一体の改革」の一環として、2006年度から国の負担割合は3分の1に引き下げられ、残る3分の2は都道府県が負担し、その財源は地方交付税制度によって保障される仕組みとなっています。\n\nこの制度は、地方公共団体の財政力の差によって教育条件に格差が生じることを防ぎ、全国どこでも一定水準の教員を確保できるようにすることを狙いとしています。少人数学級の推進など教職員定数の改善が議論される際には、この国庫負担制度の在り方や財源確保の方法もあわせて論点となることが多く、教育財政の持続可能性を考える上で欠かせない制度の一つとなっています。",
