    body: "ゆとり教育とは、1980年に施行された学習指導要領以降、詰め込み教育への反省から、学習内容や授業時数を削減し、児童生徒にゆとりを持たせながら思考力や主体性、いわゆる「生きる力」の育成を重視する方向で進められた一連の教育政策を指す通称です。学術的・行政的な正式名称ではありませんが、社会的に広く定着した呼称として用いられます。\n\n代表的な施策として、学校週5日制の段階的導入(1992年に月1回、1995年に月2回、2002年度から完全実施)、教育内容の3割削減とされた2002年度施行の学習指導要領、そして教科の枠を超えた課題解決的な学びを行う「総合的な学習の時間」の創設などが挙げられます。\n\n2000年代半ば以降、国際学力調査(PISA)の結果低下などを背景に学力低下論が高まり、2008年改訂・2011年度全面実施の学習指導要領では授業時数や学習内容が増加に転じました。この転換はしばしば「脱ゆとり教育」と呼ばれ、ゆとり教育をめぐる評価は現在も教育政策史上の論点の一つとなっています。",
