    body: "就学義務の猶予・免除は、学校教育法第18条を根拠とする制度で、病弱、発育不完全その他やむを得ない事由のために就学が困難と認められる学齢児童生徒について、市町村教育委員会が保護者の願い出に基づき就学義務を猶予または免除できるとするものです。手続の詳細は学校教育法施行規則第34条などに定められています。\n\n猶予は一定期間就学を猶予するもの、免除は就学義務そのものを免除するものであり、いずれも保護者からの申請が前提で、教育委員会が職権で一方的に猶予・免除を行うことはできません。申請には医師の診断書など、事由を裏付ける書類の添付が求められます。\n\n近年は特別支援教育の充実や医療的ケア児支援の進展により、重い病気や障害があっても学びの機会を確保する方向が重視されており、猶予・免除の運用は慎重に行われるべきものとされています。不登校を理由とした安易な適用は認められておらず、就学義務の原則を踏まえた運用が求められています。",
