    body: "へき地教育振興法は1954年に制定された法律で、教育の機会均等の趣旨に基づき、交通不便な山間・離島などのへき地における教育の特殊事情を踏まえ、国および地方公共団体が講ずべき施策を明らかにすることで、へき地教育の水準向上を図ることを目的としています。\n\n具体的な施策として、へき地学校の施設整備に対する国庫補助、教材・図書の整備、通学困難な児童生徒のための通学バス・寄宿舎の整備などが定められています。また、へき地学校に勤務する教職員に対しては、都道府県の条例に基づき「へき地手当」が支給され、勤務環境の厳しさを踏まえた処遇上の配慮がなされています。\n\n過疎化・少子化が進む中で、へき地校の統廃合とICTを活用した遠隔授業の導入が同時に進んでおり、法制定当初とは異なる形でへき地教育の在り方が問われています。GIGAスクール構想による1人1台端末の整備は、へき地校における教育機会の確保にも寄与しています。",
