    body: "JASSO給付型奨学金は、経済的理由により進学が困難な学生を対象に返還を要しない形で生活費等を支給する制度で、2017年度に一部先行実施され、2018年度から本格実施された。2020年度からは「大学等における修学の支援に関する法律」(令和元年法律第8号)に基づく高等教育の修学支援新制度の一部として、授業料等減免とセットで運用されるようになり、住民税非課税世帯及びそれに準ずる世帯の学生が主な対象となっている。\n\n支給額は国公立・私立、自宅通学・自宅外通学の別により異なり、世帯収入に応じて満額・2/3・1/3の3段階に区分される。対象となるには、進学先が国が定める要件を満たす「確認大学等」であることに加え、学業成績や学習意欲に関する要件も設けられている。財源には消費税率引き上げによる増収分の一部が充てられており、少子化対策・教育格差是正の観点からも位置づけられている。\n\n2024年度以降は多子世帯や私立大学理工農系学部の学生への対象拡大が行われるなど、対象範囲の見直しが継続的に進められている。貸与型奨学金と異なり返還義務がないため、貧困の世代間連鎖を断ち切る施策として期待される一方、財源の持続可能性や対象基準の在り方が政策論議の対象となっている。",
