    body: "総合学科は、1994年度(平成6年度)に制度化された高等学校の学科類型で、普通科・専門学科(職業学科等)に並ぶ「第三の学科」として位置づけられる。生徒が「産業社会と人間」「情報に関する基礎的科目」「課題研究」などの必履修科目を中心に、幅広い選択科目群の中から自身の興味・関心や進路希望に応じて科目を選び、学年をまたいだ単位制のもとで学ぶことを特徴とする。制度化初年度は全国7校で開設され、その後全国的に拡大した。\n\n総合学科は、普通科と職業学科の垣根を越えた「生徒の個性を生かす教育」を目指す高校教育改革の一環として導入された。学年制ではなく単位制を基本とし、進路探究学習を通じて生徒自身が将来設計を考えながら科目選択を行う点が特色である。専門学科ほど職業に直結した教育課程ではないが、普通科よりも自由度の高い科目選択が可能で、多様な系列(産業・情報・福祉・国際等)を設けている学校が多い。\n\n2022年度からは、普通科改革により「学際領域に関する学科」「地域社会に関する学科」など新たな学科類型も設けられたが、総合学科は選択履修による総合的な学びという点で独自の位置を占め続けている。全国総合学科高等学校長協会等が設置校間の連携や実践交流を行っている。",
