    body: "学校図書館法は1953年(昭和28年)、議員立法として制定された。全国学校図書館協議会等による設置運動を背景に成立した法律で、学校図書館単独を対象とする法律としては世界初とされる。すべての小・中・高等学校等に学校図書館を設置することを義務づけ、学校図書館の運営に関する専門的職務を掌る「司書教諭」の配置について定めている。\n\n司書教諭は教諭が司書教諭の資格(講習修了等)を取得した上で発令される職で、制定当初は当分の間置かないことができるとする附則(経過措置)があったため、実際の配置は進まなかった。1997年の法改正により、12学級以上の学校には司書教諭を必ず置くことが義務化され、配置が本格化した。一方、司書教諭とは別に、図書館の日常業務を担う専任職員としての「学校司書」は法制定当初から慣行的に置かれてきたが、法律上の位置づけがないまま長く運用されてきた。\n\n2014年の法改正により、学校司書についても新たに第6条が設けられ、その配置に努めることが法律上明記された。これにより、学校図書館の運営は司書教諭(教員)と学校司書(専門的職員)が協働して担う体制が制度的に位置づけられた。学校図書館は読書活動の推進拠点であるとともに、探究学習や情報活用能力の育成を支える「学習・情報センター」としての機能も重視されている。",
