    body: "免許外教科担任は、教育職員免許法附則第2項に基づく例外的な制度で、中学校・高等学校・特別支援学校中学部/高等部等において、ある教科の免許状を持つ教員を採用できない事情がある場合に、他教科の免許状を持つ教員が都道府県教育委員会の許可を受けて、その教科の教員免許状なしに1年以内の期間、教科を担任することを認めるものである。日本の教員免許制度は学校種・教科ごとに対応する免許状を有することを原則とする「相当免許状主義」を採るが、この制度はその例外として位置づけられる。\n\n許可にあたっては、当該教科の免許状を持つ教員を採用するためのあらゆる努力を尽くしてもなお採用できないことが前提とされ、単に授業時数の平準化を目的とした運用は認められない。また、免許外教科を担任する時間数は、原則としてその教員が本来担当する免許教科の週授業時数の2分の1を超えないことなどの目安が国から示されている。臨時免許状の授与(免許状を持たない者に一定期間有効な免許状を与える制度)とは異なる仕組みである。\n\n特に生徒数の少ない小規模中学校や離島・過疎地域の学校で、専門教科の免許状を持つ教員を十分に配置できない場合の対応として活用されてきたが、教育の専門性・質の確保の観点から本来は解消が望ましい例外措置とされ、文部科学省は許可の縮減に向けた指針を示している。",
