    body: "通学区域制度は、市町村教育委員会が住民の居住地に応じてあらかじめ通学区域(校区)を設定し、それに基づいて就学すべき学校を指定する仕組みである。学校教育法施行令第5条により、市町村教育委員会は就学予定者の保護者に対し、入学期日の通知とあわせて就学すべき学校を指定することとされており、通学区域はこの指定の基準として機能する。\n\n従来は居住地に基づく学校指定が原則とされてきたが、1997年の文部省(当時)通知等を契機に、教育委員会の判断により一定の要件のもとで保護者の意向を踏まえた学校選択を認める「学校選択制」を導入する自治体が増えた。また、いじめ・いじめの疑いや通学の利便性、部活動等の事情により、指定された学校とは別の学校への就学を認める「指定校変更」や、区域外就学の制度も、通学区域制度を前提とした例外的な弾力化措置として位置づけられる。\n\n通学区域は地域コミュニティと学校との結びつきを保ち、児童生徒の安全な通学や地域における学校の計画的配置を支える一方、近年は少子化に伴う学校統廃合、学校選択制の広がり、私立・国立学校への進学選択など、就学をめぐる状況の多様化により、区域の在り方や運用の見直しが各地で議論されている。",
