    summary:
      "生活保護法に基づく8種類の扶助の一つで、義務教育を受けるために必要な学用品費・教材費・給食費等を支給する制度。",
    body: "教育扶助は、生活保護法(1950年)が定める8種類の扶助(生活・教育・住宅・医療・介護・出産・生業・葬祭)の一つで、生活保護を受給する世帯の児童生徒が義務教育を受けるために必要な費用を金銭で支給するものである。対象となるのは小学校・中学校(義務教育学校を含む)に在籍する児童生徒で、支給される費目には基準額として定められる学用品費のほか、教材費、通学のための交通費、学校給食費、学級費等が含まれる。\n\n義務教育段階を対象とする教育扶助に対し、高等学校等に在籍する子どもの就学に必要な費用は、教育扶助ではなく「生業扶助」の一類型である高等学校等就学費として支給される。この区分は、生活保護法上の義務教育が小中学校段階に限られることに由来する。教育扶助費の基準額は厚生労働大臣が定め、地域の級地区分等に応じて設定されている。\n\n生活保護世帯の子どもに対しては、教育扶助のほかにも、生活保護世帯に限らず低所得世帯を広く対象とする就学援助制度があり、両制度は対象範囲や支給根拠法が異なりつつ、貧困家庭の子どもの学びを支える重層的なセーフティネットを構成している。子どもの貧困対策として、教育扶助・就学援助を含む経済的支援の在り方は継続的に議論されている。",
