    body: "高校生等奨学給付金は、高等学校等就学支援金制度による授業料支援ではカバーされない「授業料以外の教育費」の負担軽減を目的として、2014年度(平成26年度)に創設された給付金制度である。支給対象は、生活保護受給世帯や住民税所得割非課税世帯など低所得の世帯に属する高校生等(全日制・定時制・通信制、高等専門学校、専修学校高等課程等を含む)の保護者であり、都道府県を実施主体として国が費用の一部を補助する形で運用されている。\n\n支給対象となる費用には、教科書費、教材費、学用品費、通学用品費、教科外活動費、生徒会費、PTA会費、入学学用品費、修学旅行費、通信費等が含まれ、授業料そのものは対象外である。支給額は、国公立・私立の別、生活保護世帯か非課税世帯か、扶養する子どもの人数(第1子・第2子以降)などにより異なる。給付金は返還を要しない点で、貸与型の奨学金とは性格が異なる。\n\n2020年度の高等学校等就学支援金制度の見直し(私立高校授業料の実質無償化拡大)と併せて、授業料以外の教育費負担の軽減策としての高校生等奨学給付金の役割は一層重視されるようになった。近年は対象となる所得基準の見直しや支給額の拡充が段階的に行われており、高校段階における教育の機会均等を支える施策として位置づけられている。",
