    body: "小学校高学年の教科担任制は、従来学級担任が全教科を指導する学級担任制を基本としてきた小学校において、5・6年生を対象に、外国語・理科・算数・体育等の教科について、当該教科を専門とする教員が複数学級を横断して指導する体制である。中央教育審議会が2021年1月の答申「『令和の日本型学校教育』の構築を目指して」において、令和4年度を目途に本格導入を図るべきと提言したことを受け、文部科学省は2022年度から教科担任制の推進に必要な教職員加配定数の充実(4年間で3800人程度の定数改善)を進めた。\n\n教科担任制導入の狙いは、教科の専門性を生かした授業の質の向上、中学校への進学に向けた学習・生活面での円滑な接続(いわゆる「中1ギャップ」の緩和)、及び教員一人当たりの授業準備負担の軽減や複数教員による児童理解の充実にある。優先的に専科指導の対象とすべき教科として、外国語、理科、算数、体育が挙げられている。\n\nその後の中央教育審議会の議論では、教科担任制の対象学年をさらに3・4年生にも拡大する方向性が示され、2025年度以降段階的に広げる工程表が示されるなど、制度の適用範囲は拡大が検討されている。教科担任制の実施には、専科教員の確保や時間割編成の工夫、学校規模による実施可能性の差など、実務上の課題も伴う。",
