    body: "学齢簿は、学校教育法施行令第1条に基づき、市町村教育委員会がその区域内に住所を有する学齢児童(満6歳から満12歳に達するまでの就学義務のある子ども)及び学齢生徒(それに続く中学校段階の就学義務のある子ども)について編製する公簿である。市町村の住民基本台帳に基づいて作成され、氏名、生年月日、保護者の氏名・住所等の情報が記載される。\n\n学齢簿は、市町村における就学事務の基礎資料として機能し、就学時健康診断の通知、就学すべき学校(指定校)の通知、就学義務の猶予・免除の判断、転出入や就学校変更の管理など、学齢児童生徒の就学に関する一連の手続の起点となる。毎年10月1日現在で作成され、翌年度に小学校へ入学する子どもについては、就学時健康診断の実施や入学期日・就学すべき学校の通知の基礎データとして用いられる。\n\n近年は、外国人の子どもの就学状況の把握、いわゆる「不就学」や長期欠席の実態把握においても学齢簿の情報が重要な役割を果たしており、住民基本台帳との照合を通じて、住民登録はあるが学校に在籍していない可能性のある子どもを把握する取組にも活用されている。学齢簿の適切な管理は、義務教育の機会を保障する行政上の基盤の一つとして位置づけられる。",
