    summary:
      "教育委員会の事務を統括する責任者。2015年の地方教育行政法改正により、教育委員長と教育長を一本化した「新教育長」を首長が議会同意を得て直接任命する制度に変わった。",
    body: "教育長は、教育委員会の事務局の事務を統括し、教育委員会を代表する責任者である。地方教育行政の組織及び運営に関する法律(地教行法)に基づき設置される。2015年(平成27年)3月までの制度では、教育委員会の委員の互選により選ばれる非常勤の「教育委員長」と、委員会から任命される常勤の事務局トップとしての「教育長」が別々に存在し、責任の所在が分かりにくい、迅速な意思決定が難しいといった課題が指摘されていた。\n\n2014年の地教行法改正(2015年4月施行)により、教育委員長と教育長を一本化した「新教育長」が創設された。新教育長は、教育委員会の委員としての身分を持ちながら、地方公共団体の長(首長)が議会の同意を得て直接任命し、任期は3年(委員は4年)とされ、教育委員会の会務を総理し、教育委員会を代表する立場となった。あわせて、首長が主宰し教育政策の大綱等を協議する「総合教育会議」も新設され、首長の教育行政への関与を強めつつ、教育委員会の政治的中立性・継続性・安定性は引き続き確保する制度設計とされた。\n\nこの改正は、大津市いじめ自殺事件(2011年)を契機とした教育委員会の危機対応能力や責任の所在への批判を背景の一つとしており、教育長のリーダーシップの明確化と、首長との連携強化による迅速な教育行政の実現を狙いとしている。",
    relatedSlugs: ["kyoiku-iinkai", "sogo-kyoiku-kaigi", "kyoiku-seijiteki-churitsusei"],
