    summary:
      "第2次安倍内閣が2013年1月の閣議決定で設置した、首相主導の教育政策の提言機関。いじめ対策、教育委員会制度改革、大学改革、学制改革などを提言した。",
    body: "教育再生実行会議は、平成25（2013）年1月15日の閣議決定により、内閣総理大臣の下に開かれた会議です。首相、官房長官、文部科学大臣兼教育再生担当大臣と有識者で構成され、教育の再生を「経済再生と並ぶ最重要課題」と位置づける政権の方針のもと、中央教育審議会などへの検討課題の提示を含む教育改革の推進役を担いました。なお、同種の首相直属の会議として、1980年代の臨時教育審議会がありました。\n\n同会議は複数次にわたる提言を重ねました。第1次提言（2013年2月）はいじめ問題への対応を扱い、道徳の教科化やいじめ対策の法制化などを盛り込み、後の「いじめ防止対策推進法」の制定につながりました。続く提言では教育委員会制度の在り方、大学教育、高校教育と大学教育の接続・大学入学者選抜、学制の在り方（6・3・3・4制の見直し）などが取り上げられ、地方教育行政法の改正（2015年施行）、高大接続改革、義務教育学校の創設といった施策に影響を与えました。\n\n同会議は2021年12月に設置された後継の「教育未来創造会議」へと引き継がれたとされます。政治主導で教育政策の論点を設定する手法は、審議会の独立性や教育の政治的中立性との関係から評価が分かれており、教育政策の決定過程を考える際の重要な事例です。",
