    body: "教育未来創造会議は、令和3（2021）年12月に政府が設置した会議で、第1回会議は同月27日に「我が国の未来を担う人材の育成の在り方について」を議題に開かれました。高等教育を含む教育の在り方について国の方向性を示し、学び直しなど教育と社会の接続を多様化・柔軟化することをねらいとし、教育への投資を「新しい資本主義」の実現と結びつけて論じる点に特色があります。教育再生実行会議の後継会議と位置づけられています。\n\n同会議は提言を取りまとめ、令和4（2022）年5月10日に第一次提言「我が国の未来をけん引する大学等と社会の在り方について」、令和5（2023）年4月27日に第二次提言「未来を創造する若者の留学促進イニシアティブ」を公表しました。第一次提言については、進捗を管理するための工程表が作成され、令和5年9月に改訂されています。\n\n提言は、大学・高専等の機能強化、学び直し（リカレント教育）の推進、若者の海外留学の促進など、中央教育審議会や各省庁の個別施策に影響を与える政策の方向づけとして位置づけられます。審議会の答申とは異なり、首相官邸・内閣官房主導の枠組みで政策課題を提示するものであり、教育政策の決定過程を理解するうえで押さえておきたい存在です。",
