    body: "食育基本法は、平成17（2005）年6月17日に公布、同年7月15日に施行された法律です。食生活の乱れや、食に関する知識・判断力の低下が指摘される中で、食育を生きる上での基本であり、知育・徳育・体育の基礎となるものと位置づけ、国民運動として総合的・計画的に推進することを目的としています。国の食育推進会議が、同法に基づき食育推進基本計画を作成する仕組みです。\n\n基本計画は概ね5年ごとに見直されます。第4次計画は令和3（2021）年3月に決定され、令和3年度からの5年間を対象に、生涯を通じた心身の健康を支える食育、持続可能な食を支える食育、「新たな日常」やデジタル化に対応した食育を重点事項としました。令和8（2026）年6月24日には第5次食育推進基本計画が食育推進会議で決定され、令和8年度からおおむね5年間を対象に、学校等での食や農に関する学びの充実や、大人の食育の推進などを重点事項に掲げています。\n\n学校においては、食育は学校給食の活用や教科・特別活動・総合的な学習の時間などを通じて取り組まれ、2005年に創設された栄養教諭が中心的な役割を担います。文部科学省は「食に関する指導の手引」を示し、食に関する指導の全体計画の作成などを学校に求めています。食育は学校教育の枠を超えて、家庭、地域、農林漁業者などとも連携して進められる点が特徴です。",
