    summary:
      "食に関する指導と学校給食の管理を一体的に担う教員として、2005年度に創設された職。栄養教諭免許状を持ち、児童生徒の食育の中核となる。",
    body: "栄養教諭制度は、「学校教育法等の一部を改正する法律」（平成16年法律第49号、平成16年5月21日公布）により創設され、平成17（2005）年4月1日に施行された制度です。教育職員免許法の改正部分は平成16年7月1日から施行され、栄養教諭免許状が新設されました。食生活の乱れが深刻化する中で、学校における食に関する指導を充実させることが背景にあります。\n\n栄養教諭は、児童生徒の栄養の指導および管理をつかさどる教員です。職務は大きく二つに分かれ、一つは偏食、肥満、食物アレルギーなどのある児童生徒への個別的な相談指導や、学級担任等と連携した教科・特別活動での食に関する指導、もう一つは学校給食の栄養管理・衛生管理・検食などの給食管理です。この二つを一体的に行うことで、給食を「生きた教材」として活用した食育を進めることができます。従来の学校栄養職員は栄養士・管理栄養士の免許をもとに給食管理を主に担う職でしたが、栄養教諭は教育職員として指導面を担う点が大きく異なります。\n\n栄養教諭の配置は、地方公共団体や設置者の判断によることとされており、都道府県間で配置状況に差があることが課題として指摘されています。制度創設当初は全国で数十人だった栄養教諭は、その後大きく増加しました。第4次食育推進基本計画でも、栄養教諭の一層の配置促進が掲げられています。",
