    summary:
      "2016年の教育公務員特例法改正で導入された、教員のキャリア段階別の資質向上の指標と、それを策定する教育委員会・大学等の協議組織。",
    body: "教員育成指標は、校長および教員としての資質の向上に関する指標で、平成28（2016）年11月の教育公務員特例法の一部改正により制度化され、平成29（2017）年4月1日に施行されました。任命権者（都道府県・指定都市の教育委員会等）は、教員の職責、経験、適性に応じて身に付けるべき資質を体系的に示した指標を定めることになります。文部科学大臣は、指標の策定に関する指針を定めることとされ、指針は平成29年3月31日に策定されました。\n\n指標を策定するため、任命権者は教育委員会と、関係する大学等で構成される「教員育成協議会」を組織します。協議会では、指標に関する事項に加え、教員の養成や資質・能力の向上に関する事項を協議します。任命権者は、指標を踏まえて教員研修計画を定めることとされ、これにより、養成・採用・研修を一体的に捉えた教員育成の仕組みが整えられました。\n\nその後、令和4（2022）年には教員免許更新制が廃止されるとともに、教育公務員特例法と教育職員免許法の改正により、研修履歴の記録の作成や、それを活用した資質向上に関する指導助言が制度化されました。これに合わせて同年8月に指針も改正され、多くの自治体が特別な配慮を要する子供への対応やICT活用などを盛り込んで指標を改訂しています。",
