      "高度な専門性を備えた新人教員と、スクールリーダーとなる中核的教員の養成に特化した専門職大学院。2008年度に開設され、教職修士（専門職）の学位を授与する。",
    body: "教職大学院は、教員養成に特化した専門職大学院で、中央教育審議会の平成18（2006）年の答申「今後の教員養成・免許制度の在り方について」を受けて、平成19年度に制度化され、平成20（2008）年度から開設されました。学部段階で教員免許を取得した新人教員を対象とする養成と、現職教員を対象とする高度化の二つの機能を持ち、学校現場で求められる実践的な指導力を備えた教員、特にスクールリーダーとなる中核的教員の育成を目的としています。\n\n課程の修了要件は、専門職大学院設置基準第29条第1項により、2年以上在学し、45単位以上（連携協力校等での実習10単位以上を含む）を修得することとされています。標準修業年限は2年で、修了者には「教職修士（専門職）」の学位が授与されます。現職教員については、教職経験をもとに実習の一部を免除する特例があります。カリキュラムは、教育課程の編成・実施、教科等の実践的指導方法、生徒指導・教育相談、学級経営・学校経営、学校教育と教員の在り方といった領域に整理され、理論と実践の往還が重視されます。\n\n教職大学院は、研究者養成を主眼とする従来の教育学研究科の修士課程とは役割が異なり、学校現場との連携を前提とする点に特色があります。教員養成・研修の高度化を担う拠点として、各地の教育委員会との連携のもとで整備が進められています。",
