    body: "学校の適正規模・適正配置とは、教育効果や学校運営の観点から望ましい学校の大きさや配置のあり方を示す考え方です。学校教育法施行規則第41条は、小学校の学級数を12学級以上18学級以下とすることを標準と定めており（地域の実態その他により特別の事情があるときはこの限りでない）、第79条により中学校にも準用されます。また、「義務教育諸学校等の施設費の国庫負担等に関する法律施行令」第4条は、統合に伴う施設整備の国庫負担の要件として、学級数がおおむね12学級から18学級であることに加え、通学距離が小学校でおおむね4キロメートル以内、中学校でおおむね6キロメートル以内であることを挙げています。\n\n少子化により小規模校が増えるなか、文部科学省は平成27（2015）年1月に「公立小学校・中学校の適正規模・適正配置等に関する手引」を策定しました。手引は、学級数が標準を下回る場合に市町村が検討すべき対応策を整理しており、通学時間については「おおむね1時間以内」を一応の目安としつつ、適切な交通手段が確保できることを前提に、各市町村が地域の実情に応じて判断するとしています。学校が地域コミュニティの核としての役割を持つことにも配慮が求められます。\n\n小規模校には、きめ細かな指導がしやすい一方、集団での学び合いや多様な人間関係の形成に制約があるといった課題があるとされます。統廃合を進める場合も、小規模校を存続させる場合も、複式学級の解消やオンライン授業の活用、小中一貫教育・義務教育学校への移行などの選択肢を、地域住民との丁寧な合意形成のもとで検討することが重要です。",
