    body: "日本国憲法第26条は、すべての国民がその能力に応じて等しく教育を受ける権利を有することを保障した規定である。戦前の国家主義的な教育体制への反省から、個人の尊厳に基づき、国家が国民に対して学ぶ機会を平等に保障する近代公教育の基本理念を確立した。\n\n本条第1項は教育を受ける権利を規定し、第2項はすべての国民に対してその保護する子女に普通教育を受けさせる義務を課している。さらに義務教育の無償を定め、学校教育法や義務教育費国庫負担法などの関係法令により、公立小中学校の授業料無償や就学援助制度が具体化されている。\n\n学校現場では、不登校児童生徒の増加や経済的格差による学習機会の不平等が深刻化する中で、本条の理念に基づいた誰一人取り残さない支援が求められている。家庭環境に関わらず確かな学力と育ちを保障するための就学支援や、多様な学びの場の確保が現代教育の重要課題である。",
