    body: "教育基本法前文は、日本国憲法の精神にのっとり、民主的で文化的な国家の建設と世界の平和に寄与する教育の理念を宣言した条項である。1947年の制定時より教育の憲章として位置づけられ、2006年の全部改正においても不易の理念を継承しながら新たな時代像が示された。\n\n前文では、個人の尊厳を重んじ、真理と正義を希求し、豊かな人間性と創造性を備えた人間の育成を掲げている。国や地方公共団体は、この前文に示された精神に基づき、教育振興基本計画の策定や教育施策の総合的な展開を義務づけられている。\n\n学校現場においては、児童生徒が自他の人権を尊重し、社会の形成者として主体的に判断し行動できる市民性を育成することが求められている。地球規模の環境問題や分断が進む国際社会の中で、平和で持続可能な未来を築く教育の実践が現代の重要課題である。",
