    body: "教育基本法第9条は、学校教育を担う教員に対して高い使命感と専門性の向上を求めた規定である。2006年の全部改正に伴い、教員の崇高な使命の自覚と自己の研修に努める責務が明文化され、公務員法や教育公務員特例法の根拠として位置づけられた。\n\n本条第1項は教員が誇りと使命感を持ち、絶えず研究と修養に努めるべきことを規定している。第2項では、教員の職責の重要性を踏まえ、国や自治体に対して教員の養成や採用、研修の充実など、資質向上に必要な体制整備を講じることを義務づけている。\n\n教育環境の急速な変化に伴い、情報通信技術の活用や多様な学習支援など、教員に求められる専門性は高度化している。多忙な学校現場において、日々の授業改善や協働的な研修の時間をいかに確保し、専門職としての成長を支え続けるかが重要な課題となっている。",
