    body: "教育基本法第10条は、すべての子どもの健全な成長において家庭教育が最も基礎的な役割を果たすことを宣言した規定である。2006年の法改正によって新設され、保護者が子どもの教育について第一義的責任を有するという原理が法律上に初めて明確化された。\n\n本条第1項は、保護者が子の生活習慣の確立や自立心の育成に努めるべきことを定めている。同時に第2項では、家庭の自主性を尊重しつつ、国や地方公共団体に対して家庭教育に関する学習機会の提供や相談体制の整備など、支援施策を講じることを義務づけている。\n\n核家族化や共働き世帯の増加、地域のつながりの希薄化により、子育てに不安や孤立を感じる家庭が増加している。学校や地域が家庭と密接に連携し、過度な責任追求に陥ることなく、寄り添いながら家庭の教育力を支える協働体制の構築が不可欠となっている。",
