    body: "教育基本法第15条は、憲法の政教分離と信教の自由を教育の領域において具体化し、宗教に関する情操の尊重と公立学校の非宗教性を定めた規定である。歴史や文化の基盤としての宗教的教養の価値を認めつつ、国家による特定宗教の強制を排除している。\n\n本条第1項は、宗教に関する一般的な教養および宗教に対する寛容の態度を教育上尊重することを定めている。しかし第2項では、国および地方公共団体が設置する学校において、特定の宗教のための宗教教育その他一切の宗教的活動を行うことを禁止している。\n\n学校教育では、美術や音楽、歴史などの学習において宗教文化を客観的に教えつつ、特定宗派への肩入れを排する中立性が求められる。国際化により多様な信仰を持つ子どもが増える中で、他者の信仰を尊重する寛容の態度をいかに育むかが課題である。",
