    body: "学校教育法第2条は、学校を設置できる主体である設置者の適格要件を定めた規定である。学校教育が私的な営利事業として行われることを防ぎ、公共の福祉に資する教育機関として安定的に運営されるよう、設置主体を厳格に限定する趣旨で制定された。\n\n本条に基づき、学校は国、地方公共団体、および私立学校法に規定する学校法人のみが設置できる。また、設置した学校を適切に管理・運営する責務を負い、その経費を負担することが定められている。構造改革特別区域法による学校設置の特例も存在する。\n\n少子化の進展や自治体の財政難に伴い、公立学校の統廃合や学校法人の経営基盤の弱体化が顕在化している。教育の質と学校教育の永続性を確保するために、設置者による適切な財務管理と教育環境の適正な維持管理がこれまで以上に強く求められている。",
