    body: "学校教育法第11条は、学校における教育指導のための懲戒権の根拠を定めるとともに、体罰の厳格な禁止を明記した規定である。児童生徒の肉体的・精神的侵害を防ぎ、基本的人権を保障しながら健全な規範意識を育てるために制定された。\n\n本条は、校長および教員が必要と認めるときは監督官庁の定めるところにより懲戒を加えることができるとしつつ、体罰を加えることはできないと断定している。退学や停学、訓告などの適正な懲戒処分と、身体的苦痛を与える体罰との境界が明確に示されている。\n\n学校現場では、部活動指導や生徒指導における暴言や不適切な指導が体罰に該当するかどうかが厳しく注視されている。教員が感情的な制裁に頼ることなく、生徒との信頼関係を基盤にした対話的で教育的な指導技術を身につけることが強く求められている。",
