    body: "学校教育法第12条は、学校における児童生徒および教職員の健康保持増進を図るため、健康診断の実施を義務づけた規定である。学校という集団生活の場における感染症予防と健全な心身の発達を支援する公衆衛生施策の法的基礎として位置づけられている。\n\n本条に基づき、具体的な運用規則は学校保健安全法に委ねられている。学校医や学校歯科医、養護教諭が連携して毎学年定期に健康診断を実施し、疾病の早期発見や学校環境衛生基準に基づく教室の換気、採光、騒音等の環境管理が行われている。\n\n現代の学校では、アレルギー疾患や生活習慣病、視力低下への対応に加え、児童生徒の心の健康対策が重要な課題となっている。保健室を核とした健康相談体制の充実や、感染症流行時における迅速な衛生管理など、安全で安心な教育環境の維持が求められる。",
