    body: "学校教育法第34条は、小学校において文部科学大臣の検定を経た教科用図書、または文部科学省が著作の名義を有する教科用図書を使用しなければならないと規定している。全国的な教育水準の確保と教育の機会均等を達成するための基幹的な条項であり、中学校や高等学校等にも準用されている。\n\n本条は主たる教材としての教科書使用を義務づける一方、第2項において紙の教科書に代えて電磁的記録であるデジタル教科書を使用できる特例も設けている。さらに第3項に基づき、有益適切な図書その他の教材を副教材として補完的に使用することが認められており、各教育委員会の届出や承認等の基準に従い運用される。\n\n学校現場では、学習指導要領の内容を網羅した教科書を中核に据えつつ、児童生徒の理解度に応じた多様な副教材の適切な選定と利活用が求められる。デジタル教科書と紙媒体の相乗効果を生かした授業づくりや、家庭の経済的負担に配慮した副教材の精選が現代の教育実践における重要課題である。",
