    body: "学校教育法第35条は、性行不良であって他の児童の教育に妨げがあると認める児童があるときは、市町村教育委員会がその保護者に対して出席停止を命ずることができると定めている。学校の正常な教育秩序を維持し、他の児童生徒が安全に学ぶ権利を保障するために設けられた規定である。\n\n出席停止の要件としては、他の児童生徒への傷害や暴行、施設設備の損壊、授業の継続的な妨害などが法定されている。本措置は懲戒処分ではなく教育的配慮に基づく行政処分であるため、発令に際してはあらかじめ保護者の意見を聴取し、理由を記載した文書を交付する厳格な手続きが義務づけられている。\n\n学校および教育委員会には、出席停止期間中も対象児童生徒への個別学習指導や相談支援を継続し、円滑な復帰を導く義務がある。排除を目的とするのではなく、関係機関や専門職と密接に連携しながら児童生徒の立ち直りを支え、学校生活の再適応を促す指導体制の構築が不可欠である。",
