    body: "学校教育法第37条は、小学校に置くべき職員の職種とそれぞれの職務内容を定めた規定であり、中学校や高等学校など他校種にも準用される。学校組織の責任体制を明確にし、児童生徒の健全な育成に向けた円滑かつ組織的な学校運営を保障するための基本原則を示している。\n\n本条において、校長は校務をつかさどり所属職員を監督する最高責任者と位置づけられる。副校長は校長を助け、命を受けて校務をつかさどる職務を担う。また教頭は校長および副校長を助け、校務を整理し、必要に応じて児童生徒の教育をつかさどるとともに、校長に事故があるときはその職務を代理する。\n\n複雑化・多様化する学校教育の課題に対応するため、管理職を中心とする明確な指導力と組織的な管理運営が不可欠である。校長方針のもとで副校長や教頭が主導的な役割を果たし、教職員の協働を促す開かれた学校運営体制の確立が現代の教育現場で重視されている。",
