    body: "学校教育法第37条第14項は、学校事務職員の職務を「事務をつかさどる」と規定している。2017年の法改正以前は「事務に従事する」と定められていたが、学校運営における自律性と専門性を高めるため、自らの判断と責任で校務を処理し経営に参画する職責へと明確に再定義された。\n\n事務職員は、予算の編成および執行、施設設備の整備管理、教職員の服務や給与事務などを担う。また複数校の事務を集約して組織的に処理する共同学校事務室の制度化に伴い、業務の効率化や地域連携の推進、学校適正規模の維持に向けた各種調査分析など、より広範な教育行政実務を主導する。\n\n教員の多忙化解消や学校組織力の向上が急務とされる中、事務職員が教育活動を物質的・制度的に支える意義は極めて大きい。校長の学校経営方針を理解し、教育環境の充実に向けた財務戦略を立案・実行するなど、チーム学校の重要な一員としての活躍が期待されている。",
