    body: "学校保健安全法第23条は、大学以外の学校に学校医を置き、特別支援学校等を除き学校歯科医および学校薬剤師を置かなければならないと定めている。外部の高度な医療専門家を非常勤の公務員として委嘱し、学校における保健管理と環境衛生の専門的水準を確保するための制度的基盤である。\n\n学校医および学校歯科医は、就学時健康診断や定期健康診断を執り行い、疾病の早期発見と予防指導、学校保健委員会への参画を担う。学校薬剤師は、教室の換気、採光や照度、騒音、飲料水の水質、給食設備の衛生などに関する定期検査を行い、安全で快適な学習環境の維持に向け指導助言を行う。\n\n感染症の大流行への対応や児童生徒のアレルギー疾患、薬物乱用防止教育など、専門職三者の果たす役割は重要性を増している。学校現場が養護教諭を中心にこれらの専門家と定期的に情報を共有し、迅速な健康危機管理と予防教育を推進する連携体制の強化が課題となっている。",
