    body: "学校保健安全法第19条および施行規則に基づき、学校内での感染症のまん延を防ぐため、校長が病気にかかった児童生徒に出席停止を命じる制度である。集団生活における感染防止と、感染した児童生徒の早期回復を保障する公衆衛生上の重要な枠組みである。\n\n感染症は重大度や感染力に応じて第1種から第3種に分類される。エボラ出血熱等の重大感染症が第1種、インフルエンザやはしか等の空気やせきによる感染症が第2種、腸管出血性大腸菌感染症等が第3種である。解熱後の日数など明確な出席停止基準が設けられている。\n\n出席停止は懲戒処分とは異なり、指導要録上も欠席日数に含まれないため学習上の不利益を被らない。学校現場では家庭や医療機関との速やかな情報共有を進めるとともに、休業中の学習保障や感染者に対する偏見や差別の防止に向けた適切な指導が求められる。",
