    body: "へき地学校の級地指定基準とへき地手当給付とは、地理的環境が不利な山間部や離島に所在する公立学校に対し、教育水準の確保と教員の定着を図る制度である。1954年制定のへき地教育振興法および関係法令を根拠とし、教育の機会均等を具現化する重要施策として機能してきた。\n\n文部科学省令に基づき、駅や市街地からの距離、病院や郵便局等の生活機関への到達時間、公共交通機関の運行状況等を点数化し、1級地から5級地まで級地指定を行う。これに準ずる学校も準へき地として指定され、勤務する教員には給料月額に応じた一定割合の手当が給付される。\n\nへき地における教員の生活を支え、過疎地域における優秀な指導者の確保に大きく寄与してきた。しかし現代では、急速な人口減少と少子化による複式学級化や学校統廃合の加速、教員志望者の減少に伴うへき地配置の困難化など、制度を維持する環境の厳しさが増している。",
