    body: "小中連携教育・小中一貫教育の4つの推進類型とは、義務教育の円滑な接続と教育効果向上を目指し、学校制度や協力形態の違いにより体系化されたモデルである。2015年の学校教育法改正および文部科学省の指針に基づき、自治体の実情に応じた選択肢として整理された。\n\n具体的には、単一の学校種である「義務教育学校」、同一の設置者が設置し一体的な教育課程を編成する「併設型小中一貫校」、異なる設置者間等で連携する「連携型小中一貫校」、および既存の別個の小中学校が合同研修や乗り入れ授業で協働する「小中連携教育」に大別される。\n\n9年間の発達を見通した系統的指導や教員の相互理解が進み、生徒指導上のつまずきを早期に防ぐ効果を上げている。反面、教員同士の合同会議や行事調整による多忙化、学校施設の分離による日常的交流の制限など、持続可能な連携体制の構築が課題として指摘されている。",
