    body: "専修学校の区分体系とは、実践的な職業教育や専門技術の習得を目的とする専修学校において、対象者や教育段階に応じて設けられた3つの課程区分である。1975年の学校教育法改正により第124条以降に専修学校制度が創設され、多様な教育需要に応える基盤となった。\n\n本体系は、中学校卒業者を対象とする「高等課程（高等専修学校）」、高等学校卒業者等を対象とする「専門課程（専門学校）」、学歴資格を問わず広く一般を対象とする「一般課程」に分かれる。各課程とも修業年限1年以上、年間800時間以上の授業時数等の設置基準が定められている。\n\n産業界の即戦力となる専門職業人を輩出し、生涯学習や多様な進路選択の受け皿として確固たる地位を築いてきた。しかし、急速な少子化に伴う定員充足率の低下、教育水準の客観的な質保証、大学進学率上昇の中で専修学校独自の存在意義をいかに発揮するかが問われている。",
