    body: "高等専修学校修了者の大学入学資格付与基準とは、専修学校高等課程を修了した生徒に対し、高等学校卒業と同等に大学受験資格を認める制度である。1985年の学校教育法施行規則改正等により導入され、職業教育と学問研究の進路接続を図る公的基準として確立された。\n\n文部科学大臣の指定を受けるための要件として、修業年限が3年以上であること、総授業時数が2590時間以上であること、および高等学校の普通科目に準じた教育課程を適切に編成していることなどが規定されている。指定を受けた学校の修了者は正規の大学出願資格を得る。\n\n実践的な技能習得や不登校からの学び直しを経た生徒に対し、高等教育への門戸を広く開放した意義は非常に大きい。一方で、基準を満たすための普通教科の指導体制の維持や、専門科目とのバランスの確保、社会的な認知度の向上などが教育現場での継続的課題である。",
