    body: "各種学校の認可基準と法的地位とは、学校教育法第1条に規定される学校（一条校）や専修学校の枠組みに入らない教育施設を公的に認知する制度である。学校教育法第134条を根拠とし、戦後の教育復興期から地域社会の多様な実務教育や文化教育の受け皿として位置づけられてきた。\n\n設置には都道府県知事の認可が必要であり、各都道府県の認可基準に基づき修業年限（原則3月以上または1年以上）、年間授業時数、校地・校舎設備、教員の適格性などが審査される。外国人学校、予備校、自動車学校、各種技能訓練学校などが各種学校として認可されている。\n\n社会の多様な教育需要に迅速かつ柔軟に対応できる特長を持つ。しかし、一条校のような公的助成や税制上の優遇措置が制限されている点や、外国人学校修了者の進学資格をめぐる問題、教育水準の維持管理と経営基盤の安定が継続的な論点となっている。",
