    body: "特別免許状とは、大学の教職課程を修了していない社会人等で、専門的な学識や卓越した実務経験を有する者を学校に登用する特例制度である。1988年の教育職員免許法改正により創設され、多様な外部人材の参画によって学校教育の活性化を図ることを目的としている。\n\n授与要件として、任命権者（公立では教育委員会等）の推薦を受け、都道府県教育委員会が設置する教育職員検定を経て授与される。有効期間は10年であり、授与された都道府県内の学校においてのみ効力を持つ。英語、情報、看護、理数、芸術などの教科で主に活用される。\n\n高度な実務経験を授業に還元し、実社会と結びついた深い学びを実現する利点がある。反面、全国的な授与件数が伸び悩んでおり自治体間の運用格差が大きいことや、社会人教員に対する指導法や学級経営に関する研修支援の充実が現場での課題となっている。",
