    body: "主任制とは、学校教育法施行規則等に基づき、校長の職務を補佐し特定の校務を連絡調整する教員を配置する制度である。1975年の施行規則改正によって教務主任や学年主任が法令上明文化され、組織的で機能的な学校運営体制の確立を目指して制度化された。\n\n本制度では、教務主任、学年主任、生徒指導主事、進路指導主事等の設置が原則として義務づけられている（小規模校等の特例を除く）。校長が教諭の中から指名発令し、該当校務の企画立案や教員間の調整を担う。主任手当の支給基準なども各自治体の条例等で規定される。\n\n学校組織の意思疎通を円滑にし、ミドルリーダーとして学校運営を支える中核的意義を持つ。しかし近年では、複雑化する生徒指導や教育課程管理による主任層の業務過重が深刻化しており、主幹教諭や指導教諭との役割分担の再編や負担軽減が課題となっている。",
